mastery.solution_text:
$y=f(x-1)+2$ shifts right $1$ and up $2$: $(x,y)\to(x+1,\,y+2)$.
$(-1,1)\to(0,3)$ and $(1,-1)\to(2,1)$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw[->] (-2.7,0)--(4.2,0) node[right] {$x$};
\draw[->] (0,-1.1)--(0,3.9) node[above] {$y$};
\draw[thick,gray,dashed,<->,domain=-2.3:2.3,smooth,samples=61,variable=\x] plot ({\x},{0.5*\x*\x*\x-1.5*\x});
\draw[thick,blue,<->,domain=-1.3:3.1,smooth,samples=61,variable=\x] plot ({\x},{0.5*(\x-1)*(\x-1)*(\x-1)-1.5*(\x-1)+2});
\node[gray,below] at (-1.7,-0.3) {$y=f(x)$};
\node[blue,right] at (2.2,3.4) {$y=f(x-1)+2$};
\fill[gray] (-1,1) circle (1.5pt);
\fill[gray] (1,-1) circle (1.5pt);
\fill (0,3) circle (2pt) node[above left] {$(0,3)$};
\fill (2,1) circle (2pt) node[above right] {$(2,1)$};
\end{tikzpicture}
